PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>
PREFIX chop: <https://biomedit.ch/rdf/sphn-resource/chop/>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?diagnosis a sphn:BilledDiagnosis ;
               sphn:hasCode ?code .
    ?code a icd-10-gm:A00.0 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
  }
  FILTER NOT EXISTS {
    GRAPH ?g {
      ?procedure a sphn:BilledProcedure ;
                 sphn:hasCode ?proc_code .
      ?proc_code a chop:00.0 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>
PREFIX snomed: <http://snomed.info/id/>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?diagnosis a sphn:BilledDiagnosis ;
               sphn:hasCode ?dx_code .
    ?dx_code a icd-10-gm:A00.9 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
  }
  FILTER EXISTS {
    GRAPH ?g {
      ?prescription a sphn:DrugPrescription ;
                    sphn:hasDrug ?drug .
      ?drug sphn:hasActiveIngredient ?ingredient .
      ?ingredient sphn:hasCode ?drug_code .
      ?drug_code a snomed:63856005 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?sex (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?record a sphn:AdministrativeSex ;
            sphn:hasCode ?code .
    ?code a ?sex .
  }
  FILTER (STRSTARTS(STR(?sex), "http://snomed.info/id/"))
}
GROUP BY ?sex
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?year (COUNT(DISTINCT ?procedure) AS ?procedures)
WHERE {
  GRAPH ?g {
    ?procedure a sphn:BilledProcedure ;
               sphn:hasStartDateTime ?start .
  }
  BIND (YEAR(?start) AS ?year)
}
GROUP BY ?year
ORDER BY ?year

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?ingredient (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?prescription a sphn:DrugPrescription ;
                  sphn:hasDrug ?drug .
    ?drug sphn:hasActiveIngredient ?substance .
    ?substance sphn:hasCode ?code .
    ?code a ?ingredient .
  }
  FILTER (STRSTARTS(STR(?ingredient), "http://snomed.info/id/"))
}
GROUP BY ?ingredient
ORDER BY DESC(?patients)
LIMIT 5

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?route (COUNT(DISTINCT ?prescription) AS ?prescriptions)
WHERE {
  GRAPH ?g {
    ?prescription a sphn:DrugPrescription ;
                  sphn:hasAdministrationRouteCode ?code .
    ?code a ?route .
  }
  FILTER (STRSTARTS(STR(?route), "http://snomed.info/id/"))
}
GROUP BY ?route
ORDER BY DESC(?prescriptions)
LIMIT 5

